<script setup lang="ts">import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import PageHeader from'../../components/PageHeader.vue';import{client,errorMessage,requireData}from'../../../shared/api/client';import type{components}from'../../../shared/api/schema.gen';const route=useRoute();const language=String(route.params.language);const id=String(route.params.id);const value=ref<components['schemas']['TranslationFile']>();const error=ref('');const saved=ref(false);onMounted(async()=>{try{value.value=requireData(await client.GET('/api/admin/translations/{language}/{id}',{params:{path:{language,id}}}))}catch(cause){error.value=errorMessage(cause)}});async function save(){if(!value.value)return;for(const block of Object.values(value.value.blocks)){block.source='human';block.needsReview=false}try{requireData(await client.PUT('/api/admin/translations/{language}/{id}',{params:{path:{language,id}},body:value.value}));saved.value=true}catch(cause){error.value=errorMessage(cause)}}</script>
<template><PageHeader :title="`人工编辑译文 · ${language}`"/><p v-if="error" class="text-danger">{{ error }}</p><form v-if="value" class="grid gap-4" @submit.prevent="save"><label v-for="block in value.blocks" :key="block.id" class="grid gap-1"><span class="text-xs text-muted">{{ block.id }} · {{ block.sourceHash }}</span><textarea v-model="block.text" rows="4" class="nw-input" /></label><button class="nw-button">保存人工译文</button><p v-if="saved">已保存，未经再次翻译不会被机器内容覆盖。</p></form></template>
